// Why Code: renders Jetwing's quotation HTML (layout based on their invoice) for the PDF service
const LOGO = 'data:image/png;base64,';
const DEFAULT_BANK = `<b>NAME OF BENEFICIARY:</b> JETWING TRAVELS (PRIVATE) LTD.<br>
<b>ADDRESS:</b> "JETWING HOUSE", 46/26, NAVAM MAWATHA, COLOMBO 02, SRI LANKA.<br>
<b>ACCOUNT NO:</b> 2420409332<br>
<b>BENEFICIARY'S BANK:</b> COMMERCIAL BANK OF CEYLON PLC.<br>
<b>BRANCH:</b> FOREIGN BRANCH<br>
<b>ADDRESS:</b> 21, BRISTOL STREET, COLOMBO 01, SRI LANKA<br>
<b>SWIFT CODE:</b> CCEYLKLX<br>
<b>SORT CODE:</b> 7056003`;

const r = $json.r;
const q = r.quotation, items = r.items ?? [], c = r.contact ?? {}, cust = q.customer_block ?? {};
const esc = s => String(s ?? '').replace(/[&<>"']/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch]));
const nl = s => esc(s).replace(/\n/g, '<br>');
const fmt = n => Number(n || 0).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const fmtDate = d => d ? new Date(d + 'T00:00:00Z').toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric', timeZone: 'UTC' }).toUpperCase() : '-';

const ONES = ['', 'One', 'Two', 'Three', 'Four', 'Five', 'Six', 'Seven', 'Eight', 'Nine', 'Ten', 'Eleven', 'Twelve', 'Thirteen', 'Fourteen', 'Fifteen', 'Sixteen', 'Seventeen', 'Eighteen', 'Nineteen'];
const TENS = ['', '', 'Twenty', 'Thirty', 'Forty', 'Fifty', 'Sixty', 'Seventy', 'Eighty', 'Ninety'];
const w3 = n => { const p = []; if (n >= 100) { p.push(ONES[Math.floor(n / 100)] + ' Hundred'); n %= 100; }
  if (n >= 20) { p.push(TENS[Math.floor(n / 10)] + (n % 10 ? ' ' + ONES[n % 10] : '')); } else if (n > 0) p.push(ONES[n]); return p.join(' '); };
const words = n => { if (n === 0) return 'Zero'; const p = [];
  for (const [v, name] of [[1e9, 'Billion'], [1e6, 'Million'], [1e3, 'Thousand']]) if (n >= v) { p.push(w3(Math.floor(n / v)) + ' ' + name); n %= v; }
  if (n > 0) p.push(w3(n)); return p.join(' '); };

const cur = q.currency === 'USD' ? 'US$' : 'LKR';
const total = Number(q.total), whole = Math.floor(total), cents = Math.round((total - whole) * 100);
const inWords = `${cur} ${words(whole)}${cents ? ' and Cents ' + words(cents) : ''} Only`;

const normal = items.filter(i => !i.is_bank_charge), bank = items.filter(i => i.is_bank_charge);
const lineRow = it => `<tr><td class="sub">${esc(it.description)}${Number(it.quantity) !== 1 ? ` &times; ${fmt(it.quantity)} @ ${fmt(it.unit_price)}` : ''}</td><td class="amt">${fmt(it.total_price)}</td></tr>`;
const taxRow = Number(q.taxes) > 0 ? `<tr><td class="sub">Taxes</td><td class="amt">${fmt(q.taxes)}</td></tr>` : '';
const name = cust.name ?? c.full_name ?? '';
const block = (t, v) => v ? `<div class="blk"><b>${t}</b><br>${nl(v)}</div>` : '';

const html = `<!doctype html><html><head><meta charset="utf-8"><style>
@page { size: A4; margin: 16mm 16mm 14mm; }
body { font-family: Calibri, Carlito, Arial, sans-serif; font-size: 11pt; color: #111; margin: 0; }
.head { text-align: center; } .head img { height: 64px; }
.addr { font-size: 8pt; text-align: center; margin-top: 6px; line-height: 1.35; }
h1 { text-align: center; font-size: 12pt; margin: 18px 0 14px; letter-spacing: 1px; }
.meta { display: flex; justify-content: space-between; font-size: 10pt; }
table { width: 100%; border-collapse: collapse; margin-top: 14px; }
td { padding: 3px 6px; vertical-align: top; } .amt { width: 30mm; text-align: right; border-left: 1px solid #000; }
.hd td { border-top: 1px solid #000; border-bottom: 1px solid #000; } .hd .amt { text-align: center; }
.desc td { font-weight: bold; padding-top: 6px; } .sub { padding-left: 14px; }
.gap td { height: 22px; } .tot td { border-top: 1px solid #000; }
.words td { border-top: 1px solid #000; border-bottom: 1px solid #000; font-weight: bold; font-size: 10pt; }
.blk { font-size: 10pt; margin-top: 10px; } .two { display: flex; gap: 24px; } .two .blk { flex: 1; }
.bank { font-size: 9pt; margin-top: 16px; line-height: 1.45; }
.foot { margin-top: 22px; font-size: 9pt; } .note { margin-top: 18px; font-size: 8pt; color: #666; text-align: center; }
</style></head><body>
<div class="head"><img src="${LOGO}" alt="Jetwing Travels"></div>
<div class="addr">"JETWING HOUSE" 46/26, Navam Mawatha, Colombo 2, <b>SRI LANKA.</b> Tel:+ 94112345700 Fax: 94112345725/345724<br>
E-mail: travels@jetwing.lk Website: www.jetwingtravels.com<br>BRANCH: Ethukala, Negombo, Sri Lanka. Tel: 031-79175, 79438/9 Fax: +94-31-79277</div>
<h1>QUOTATION</h1>
<div class="meta">
  <div>${cust.company ? `<b>${esc(cust.company)}</b><br>` : ''}${cust.address ? nl(cust.address) + '<br>' : ''}${esc(cust.email ?? q.sent_to)}${cust.phone ?? c.phone ? '<br>' + esc(cust.phone ?? c.phone) : ''}</div>
  <div style="text-align:right">Quotation No: ${esc(q.quotation_number)}${q.version > 1 ? ' (v' + q.version + ')' : ''}<br>Date: ${fmtDate((q.approved_at ?? '').slice(0, 10) || null)}<br><b>Valid until: ${fmtDate(q.valid_until)}</b></div>
</div>
<table>
  <tr class="hd"><td>${esc(name.toUpperCase())}</td><td class="amt">Amount &ndash; ${cur}</td></tr>
  ${cust.trip_description ? `<tr class="desc"><td>${nl(cust.trip_description)}</td><td class="amt"></td></tr>` : ''}
  ${normal.map(lineRow).join('')}${taxRow}
  ${bank.length ? `<tr class="gap"><td></td><td class="amt"></td></tr>${bank.map(lineRow).join('')}` : ''}
  <tr class="gap"><td></td><td class="amt"></td></tr>
  <tr class="tot"><td>Grand Total</td><td class="amt">${fmt(q.total)}</td></tr>
  <tr class="words"><td colspan="2">${esc(inWords)}</td></tr>
</table>
<div class="two">${block('Inclusions', q.inclusions)}${block('Exclusions', q.exclusions)}</div>
${block('Terms and conditions', q.terms)}
<div class="bank">${q.payment_details ? nl(q.payment_details) : DEFAULT_BANK}</div>
<div class="foot">Prepared by<br><b>${esc(cust.prepared_by ?? 'Jetwing Travels Team')}</b></div>
<div class="note">This is a quotation, not an invoice. Rates are subject to availability at the time of booking.</div>
</body></html>`;

const safe = s => String(s).replace(/[^\w.\-]+/g, '_');
return { json: { html, file_name: `${safe(q.quotation_number)}-v${q.version}.pdf`, pdf_path: `${q.enquiry_id}/${safe(q.quotation_number)}-v${q.version}.pdf`, r } };
